_cache = {}

def sprite_rgba(name):
    if name not in _DATA:
        name = "Heart"
    if name not in _cache:
        raw = zlib.decompress(base64.b85decode(_DATA[name].encode("ascii")))
        if len(raw) != WIDTH * HEIGHT * 4:
            raise ValueError(f"Invalid exact sprite payload for {name}")
        pixels = []
        i = 0
        for y in range(HEIGHT):
            row = []
            for x in range(WIDTH):
                row.append(tuple(raw[i:i+4])); i += 4
            pixels.append(row)
        _cache[name] = pixels
    return _cache[name]

EXACT_SPRITES = tuple(_DATA)
